  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Blonanserin, a CNS-active molecule with aromatic methoxy and basic amine groups, showed a brain/plasma ratio of 3.38 in human PET, supporting that similar moderately lipophilic alkaloid-like structures achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Coptisine, a related isoquinoline alkaloid, was detected in mouse brain tissue, directly supporting CNS access for the isoquinoline alkaloid class to which noscapine belongs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "N-propylnorapomorphine, a rigid polycyclic alkaloid with aromatic methoxy/catechol and N-alkylamine features, showed good brain penetration in rats and nonhuman primates, supporting CNS access for noscapine-like scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "NE40, a moderately lipophilic radiotracer with aromatic and basic amine features, demonstrated high brain uptake and washout across mice, monkey, and humans, supporting that noscapine's physicochemical profile is compatible with BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "SA6298, containing dimethoxyphenyl and basic amine motifs, showed high brain uptake in cat PET, reinforcing that the query's dimethoxyaryl/amine features do not preclude meaningful CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Noscapine is a CNS-active isoquinoline alkaloid; high-transfer analogues with similar aromatic methoxy and tertiary-amine scaffolds consistently demonstrate good BBB penetration in human and animal PET/biodistribution studies, and the physicochemical profile is favorable for passive diffusion.",
  "evidence_gaps": [
    "No direct noscapine brain/plasma or tumor concentration measurement is included in the provided evidence.",
    "The query's tertiary amine could be an efflux substrate, but the high neutral fraction and consistent CNS-active analogue data mitigate this concern.",
    "Brain tumor/glioma may alter BBB integrity; however, disruption generally increases permeability, so the pass prediction is conservative."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

